SELECT muc.*, mu.nickname as userName, ci.coupon_name, ci.coupon_type
FROM member_user_coupon_usage muc
LEFT JOIN coupon_info ci ON muc.coupon_id = ci.id
LEFT JOIN member_user mu ON muc.user_id = mu.id
WHERE muc.deleted = 0

    AND muc.coupon_id = #{reqVO.couponId}


    AND muc.order_id = #{reqVO.orderId}


    AND muc.order_no = #{reqVO.orderNo}


    AND mu.nickname LIKE CONCAT('%', #{reqVO.userName}, '%')

ORDER BY muc.id DESC

SELECT coupon_id as couponId, sum(numbers) as totalCount FROM member_user_coupon_usage WHERE coupon_id IN
#{couponId}
GROUP BY coupon_id
